// Creates secrets/local.mjs from deployed bundles (run on the machine that has them; values are never printed),
// then checks that build-bundle.mjs + the repos give back the same code.
// Usage: node scripts/secrets-from-bundle.mjs <iran bundle> <cloudflare bundle> <implant-frontend dir>
import fs from 'node:fs'; import path from 'node:path'; import url from 'node:url'; import os from 'node:os'; import crypto from 'node:crypto'; import { execFileSync } from 'node:child_process';
const root = path.join(path.dirname(url.fileURLToPath(import.meta.url)), '..');
const [ir, cf, fe] = process.argv.slice(2); if (!ir || !cf || !fe) { console.error('usage: node scripts/secrets-from-bundle.mjs <iran bundle> <cloudflare bundle> <frontend dir>'); process.exit(2); }
const read = f => fs.readFileSync(f, 'utf8');
const parts = s => { const i = s.indexOf('const ASSETS='), j = s.indexOf('\n', i), c = s.indexOf('\nconst CODE=', j), ce = c >= 0 ? s.indexOf('\n', c + 1) : -1;
  return { head: s.slice(0, i), A: JSON.parse(s.slice(i + 13, j).replace(/;\s*$/, '')), noCode: c >= 0 ? s.slice(0, c + 1) + s.slice(ce + 1) : s, rest: s.slice(j + 1) }; };
const I = parts(read(ir)), C = parts(read(cf));
const one = (re, t, what) => { const m = t.match(re); if (!m) throw new Error('not found: ' + what); return m[1]; };
const PW = {}; for (const m of one(/const PW_HASH=\{([^}]*)\};/, I.head, 'PW_HASH').matchAll(/'([0-9a-f]{64})':'(\w+)'/g)) PW[m[1]] = m[2];
const LF = {}; for (const m of one(/const LF_DEF = \{([^}]*)\};/, I.rest, 'LF_DEF').matchAll(/(\w+): '([^']*)'/g)) LF[m[1]] = m[2];
const fa2en = t => t.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const texts = [I.head, I.A['/'].d, I.A['/f'].d, I.A['/p'].d, I.A['/probe'].d], ph = new Set(); /* same order as the repo placeholders */
for (const t of texts) for (const m of t.matchAll(/(?<!\d)09\d{9}(?!\d)|۰۹[۰-۹]{9}/g)) ph.add(fa2en(m[0]));
const PHONES = {}; [...ph].forEach((n, i) => { PHONES['0912000000' + (i + 1)] = n; });
const sender = one(/const SENDER='([^']*)';/, I.head, 'SENDER'), em = [...new Set(I.A['/'].d.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+\.[A-Za-z.]{2,}/g) || [])].filter(x => x !== sender);
const S = { PW_HASH: PW, EMAIL_HINT: em[0] || ((I.A['/'].d.split(sender).length > 2) ? sender : ''), BACKUP_HASH: one(/const BACKUP_HASH='([0-9a-f]*)';/, I.rest, 'BACKUP_HASH'), IMPORT_KEY: one(/const IMPORT_KEY='([^']*)';/, I.head, 'IMPORT_KEY'),
  IMPORT_KEY_CF: one(/const IMPORT_KEY='([^']*)';/, C.head, 'IMPORT_KEY (cf)'), SENDER: one(/const SENDER='([^']*)';/, I.head, 'SENDER'),
  APPS_SCRIPT_DEPLOYMENT_ID: (I.A['/'].d.match(/AKfycb[\w-]+/) || [''])[0], LF_DEF: LF, PHONES };
fs.mkdirSync(path.join(root, 'secrets'), { recursive: true });
fs.writeFileSync(path.join(root, 'secrets', 'local.mjs'), '// generated by scripts/secrets-from-bundle.mjs — never commit\nexport default ' + JSON.stringify(S, null, 2) + ';\n');
console.log('secrets/local.mjs written:', Object.entries(S).map(([k, v]) => k + (typeof v === 'object' ? '(' + Object.keys(v).length + ')' : (v ? '(set)' : '(empty)'))).join(' '));
/* check: rebuild with the APK that is inside the deployed bundle */
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'chk-')); fs.mkdirSync(path.join(tmp, 'dist'));
fs.writeFileSync(path.join(tmp, 'dist', 'implant-plan.apk'), Buffer.from(I.A['/implant-plan.apk'].d, 'base64'));
const md5 = t => crypto.createHash('md5').update(t).digest('hex');
for (const [name, P, target] of [['iran', I, 'iran'], ['cloudflare', C, 'cloudflare']]) {
  const out = path.join(tmp, name + '.mjs');
  execFileSync(process.execPath, [path.join(root, 'scripts', 'build-bundle.mjs'), fe, tmp, out, '--target', target], { stdio: 'ignore' });
  const b = read(out).replace(' /* default lab-feedback password hashes: not in git (secrets/local.mjs) */', '');
  console.log(name + ': rebuilt == deployed (without the old embedded source copy):', b === P.noCode, md5(b) === md5(P.noCode) ? '' : '(differs)');
}
fs.rmSync(tmp, { recursive: true, force: true });
